class Solution {
  public int countBinarySubstrings(String s) {
    int n = 0, pre = 0, curr = 1;
    for (int i = 0; i < s.length() - 1; i++) {
      if (s.charAt(i) == s.charAt(i + 1)) {
        curr++;
      } else {
        pre = curr;
        curr = 1;
      }
      if (pre >= curr) {
        n++;
      }
    }
    return n;
  }
}

class Solution:
    def countBinarySubstrings(self, s: str) -> int:
        n = pre = 0
        curr = 1
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                curr += 1
            else:
                pre = curr
                curr = 1
            if pre >= curr:
                n += 1
        return n

impl Solution {
    pub fn count_binary_substrings(s: String) -> i32 {
        let mut n = 0;
        let mut pre = 0;
        let mut curr = 1;
        let len = s.len() - 1;
        let bytes = s.as_bytes();
        for i in 0..len {
            if bytes[i] == bytes[i + 1] {
                curr += 1;
            } else {
                pre = curr;
                curr = 1;
            }
            if pre >= curr {
                n += 1;
            }
        }
        return n;
    }
}

